const { execFileSync, spawn } = require("node:child_process");
let key = (process.env.AIDC_API_KEY || "").trim();
if (!key && process.platform === "darwin") {
  try {
    key = execFileSync("/usr/bin/security", ["find-generic-password", "-a", "aidc-design-engine", "-s", "AIDC MCP API Key", "-w"], { encoding: "utf8", stdio: ["ignore", "pipe", "ignore"] }).trim();
  } catch {
    process.stderr.write("AIDC MCP: configured API key is unavailable in macOS Keychain.\n");
    process.exit(1);
  }
}
if (!key) {
  process.stderr.write("AIDC MCP: a registered API key must be configured before startup.\n");
  process.exit(1);
}
const windows = process.platform === "win32";
const child = spawn(windows ? "cmd.exe" : "npx", windows ? ["/d", "/s", "/c", "npx -y aidc-mcp-server@0.2.4"] : ["-y", "aidc-mcp-server@0.2.4"], {
  env: { ...process.env, ...(key ? { AIDC_API_KEY: key } : {}) },
  stdio: "inherit",
  windowsHide: true
});
child.on("error", () => { process.stderr.write("AIDC MCP: server could not be started.\n"); process.exit(1); });
child.on("exit", (code) => process.exit(code == null ? 1 : code));
for (const signal of ["SIGINT", "SIGTERM"]) process.on(signal, () => child.kill(signal));
